      "Child: Is that Tom?",
      "Woman: Yes, that's Tom. He's flying his kite.",
      "Child: Who's the girl under the tree?",
      "Woman: The girl with the ice cream?",
      "Child: Yes.",
      "Woman: That's Lucy. She loves ice cream.",
      "Woman: Can you see the man on the chair?",
      "Child: The man with the newspaper?",
      "Woman: Yes, he's reading. His name's Ben.",
      "Child: And who's that woman with the dog?",
      "Woman: That's Grace. She walks her dog in the park every day.",
      "Woman: Look at the boy on the bike.",
      "Child: Is that Sam?",
      "Woman: No, that's Nick. He's very good at riding his bike.",
      "Child: There's a girl with a balloon.",
      "Woman: Oh yes. Her name's Anna.",
      "Child: Anna?",
      "Woman: Yes. Her balloon is red."
